:root {
  --card-bg: #ffffff;
  --header-bg: #0a3d62;
  --header-text: #ffffff;
  --subtitle-text: #a8d4f5;
  --badge-bg: #1e88e5;
  --badge-text: #ffffff;
  --gold-bg: #fffbea;
  --gold-border: #f9c513;
  --gold-rank: #b8860b;
  --silver-bg: #f6f8fb;
  --silver-border: #9eb4cc;
  --silver-rank: #607d8b;
  --bronze-bg: #fff5ef;
  --bronze-border: #d4845a;
  --bronze-rank: #a0522d;
  --normal-bg: #fafafa;
  --normal-border: #e0e0e0;
  --normal-rank: #9e9e9e;
  --name-color: #1a1a2e;
  --club-color: #607d8b;
  --time-color: #0a3d62;
  --diff-color: #9e9e9e;
  --footer-bg: #f0f6fc;
  --footer-text: #546e7a;
  --card-radius: 12px;
  --row-radius: 6px;
}

article.regatta-card {
  background: var(--card-bg);
  border-radius: var(--card-radius);
  width: 460px;
  overflow: hidden;
  border: 1px solid var(--normal-border);
}

.regatta-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
}

.trophy {
  font-size: 22px;
  line-height: 1;
}

.header-text {
  flex: 1;
}

.regatta-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--header-text);
  margin: 0;
  line-height: 1.2;
}

.regatta-subtitle {
  font-size: 11px;
  color: var(--subtitle-text);
  margin: 1px 0 0 0;
  line-height: 1;
}

.race-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.leaderboard {
  padding: 8px 10px;
}

.race-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.race-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: var(--row-radius);
  border-left: 3px solid transparent;
}

.race-row.gold {
  background: var(--gold-bg);
  border-left-color: var(--gold-border);
}

.race-row.silver {
  background: var(--silver-bg);
  border-left-color: var(--silver-border);
}

.race-row.bronze {
  background: var(--bronze-bg);
  border-left-color: var(--bronze-border);
}

.race-row.normal {
  background: var(--normal-bg);
  border-left-color: var(--normal-border);
}

.rank {
  font-size: 12px;
  font-weight: 700;
  width: 14px;
  text-align: center;
  color: var(--normal-rank);
}

.race-row.gold .rank { color: var(--gold-rank); }
.race-row.silver .rank { color: var(--silver-rank); }
.race-row.bronze .rank { color: var(--bronze-rank); }

.medal {
  font-size: 16px;
  line-height: 1;
  width: 20px;
  text-align: center;
}

.racer-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.racer-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--name-color);
  line-height: 1.2;
}

.racer-club {
  font-size: 10px;
  color: var(--club-color);
  line-height: 1.2;
}

.race-time {
  font-size: 13px;
  font-weight: 700;
  color: var(--time-color);
  letter-spacing: 0.3px;
  min-width: 54px;
  text-align: right;
}

.diff {
  font-size: 10px;
  color: var(--diff-color);
  min-width: 34px;
  text-align: right;
}

.regatta-footer {
  background: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 14px;
  border-top: 1px solid var(--normal-border);
}

.footer-detail {
  font-size: 10px;
  color: var(--footer-text);
  font-weight: 500;
}
